package com.example.rokidkeyboardbridge;
public final class RestAnimationTest {
 static int n;static void ok(boolean b,String s){n++;if(!b)throw new AssertionError(s);}
 public static void main(String[] args){String[] q={"寝返りを打って","寝たまま背伸びして","寝たまま照れた身じろぎをして","寝たまま手を振って","寝たままキス顔にして","寝たまま困った顔にして","寝たまませつない顔にして","寝たままこらえる顔にして"};for(int i=0;i<q.length;i++){EmbodiedScenePolicy p=new EmbodiedScenePolicy();p.user(q[i],1000);ok(p.correctedRest(),"explicit corrected rest route "+q[i]);ok(i<4?p.restMotion(1100)==i+1:p.restFace()==i-3,"right motion/face");ok(!RestAnimationIntent.reply(i+1).isEmpty(),"local response");p.answer("分かりました。",FullBodyPoseCatalog.Kind.NEUTRAL,1200);p.user("明日の天気は？",1300);ok(p.correctedRest(),"ordinary question keeps corrected body");ok(p.clip(1400,true)==-1,"quiet nav suppresses body overlay");}
 for(String qn:new String[]{"彼女が寝返りしてと言った","寝返りの方法を教えて","寝たままキス顔にしないで","寝返りとは何？","私は背伸びしている"})ok(RestAnimationIntent.action(qn)<0,"not local control "+qn);
 ok(!RestAnimationIntent.applies("困った顔にして",false),"standing expression does not force lying");ok(RestAnimationIntent.applies("困った顔にして",true),"lying expression works");ok(RestAnimationIntent.applies("ロキ、寝たまま手を振って",false),"prefixed explicit wave");
 for(int m=1;m<=4;m++){int distinct=0,last=-1;for(int t=0;t<=7000;t+=100){int frame=RestAnimationTimeline.frame(m,t);ok(frame>=0&&frame<14,"bounded body frame");float mix=RestAnimationTimeline.mix(m,t);ok(mix>=0&&mix<=1,"bounded transition");if(frame!=last){distinct++;last=frame;}}ok(distinct>=4,"has animation phases");ok(RestAnimationTimeline.frame(m,100000)==9&&!RestAnimationTimeline.moving(m,100000),"finite motion settles to same corrected master");}
 EmbodiedScenePolicy p=new EmbodiedScenePolicy();p.user("ねそべって",1000);p.user("寝たままキス顔にして",2000);p.user("動いてない",3000);ok(p.restFace()==1,"redo preserves face");p.answer("やり直します。",FullBodyPoseCatalog.Kind.NEUTRAL,3200);p.user("戻って",4000);p.user("戻って",4100);ok(p.restFace()==0&&p.correctedRest(),"single undo with duplicate context keeps lying");p.user("立って",5000);ok(!p.correctedRest()&&p.posture()==0,"stand leaves rest renderer");
 System.out.println("PASS "+n+" rest animation/face/local command/finite timeline checks");}
}
